from lib import *
S = SS('w21')
steps = [
    step("本机当前的 DHCP 租约(ipconfig getpacket en0 给出的最后一个应答):BOOTP 固定头里 op = BOOTREPLY、htype = 1、hlen = 6、hops = 0,xid 是客户端选的事务编号,ciaddr、yiaddr、siaddr 都有值(局域网地址),giaddr = 0.0.0.0(没有中继),chaddr 是本机的 MAC。选项一共 11 个:报文类型 ACK(5)、服务器标识、租约时间 0x708 = 1800 秒、T1 = 817 秒、T2 = 1492 秒、子网掩码 255.255.252.0、广播地址、路由器 1 个、域名 lan、DNS 服务器 2 个、结束。ciaddr 不是 0.0.0.0,说明这个 ACK 回应的是一次续租(客户端已有地址时发的 REQUEST),而不是首次获取。T1 / 租约 = 0.454,T2 / 租约 = 0.829,和规范建议的默认值 0.5、0.875 不一样。", t=tl(S(1)), mark=lidx(S(1), 'lease_time', 'renewal_t1_time_value', 'rebinding_t2_time_value', '租约时间 1800'), done=lidx(S(1), 'op = BOOTREPLY', 'ciaddr', 'dhcp_message_type', 'subnet_mask', 'router', 'domain_name_server', '这个应答的 ciaddr'), kv=KV([['租约 / T1 / T2', '1800 / 817 / 1492 秒'], ['ciaddr 非 0', '这是一次续租的应答'], ['giaddr = 0.0.0.0', '没有 DHCP 中继'], ['选项', '掩码、网关、DNS、域名,一次交给客户端']], ['ciaddr 非 0'])),
    step("发一次真实的 DHCPDISCOVER:用一个随机的本地管理 MAC 作为 chaddr(02:00:5e:…),不发后续 REQUEST,所以没有真正占用地址。DISCOVER 共 279 字节 = 固定头 236 + magic cookie 4 + 选项 39,op = 1、flags = 0x8000(广播标志:请服务器用广播回应),选项有报文类型 53、客户端标识 61、主机名 12、请求的参数列表 55、最大报文长度 57。报文在线上:UDP 52440 → 67,IP 目的 255.255.255.255,IP 总长 307。114.2 ms 后默认网关回了 OFFER:UDP 67 → 68,IP 目的 255.255.255.255(因为广播标志),IP 总长 329、DHCP 载荷 301 字节;yiaddr 是同网段的一个地址,chaddr 就是我伪造的,选项有 10 个:租约 1800 秒、T1 = 900、T2 = 1575、子网掩码、路由器 1 个、DNS 2 个、服务器标识。我的 DISCOVER 用的是普通 UDP 套接字(源端口随机、源 IP 是本机地址),真实的 DHCP 客户端会用 UDP 68 和源地址 0.0.0.0。", t=tl(S(2)), mark=lidx(S(2), 'DISCOVER  UDP', 'OFFER  UDP', 'OFFER 内容', '选项(顺序'), done=lidx(S(2), 'DISCOVER 共 279', '选项:53', '3 秒内在 en0', '没有发 REQUEST'), b=bars([['DISCOVER 的 DHCP 载荷', 279, '279 字节'], ['OFFER 的 DHCP 载荷', 301, '301 字节']], 301, mark=[1], done=[0]), kv=KV([['DISCOVER', '广播,UDP → 67,带广播标志'], ['OFFER', '114.2 ms 后,广播回 UDP 68'], ['租约 / T1 / T2', 'OFFER 里是 1800 / 900 / 1575'], ['没发 REQUEST', 'DORA 只走了一半(D、O)']], ['OFFER'])),
    step("自己解码和 scapy 解码对 OFFER 的结果一致:选项编号 53、54、51、58、59、1、28、3、15、6 共 10 个,scapy 解出 message-type、server_id、lease_time、renewal_time、rebinding_time、subnet_mask、broadcast_address、router、domain、name_server 同样 10 个;xid 0x09562ce3 一致,op = 2,chaddr 前 6 字节一致。DHCP 包总长 301 字节 = 固定头 236 + cookie 4 + 选项 61。BOOTP 遗留的 sname(64 字节)和 file(128 字节)两个字段在 DHCP 里基本空着:非 0 字节 0 个。", t=tl(S(3)), mark=lidx(S(3), '自己解码出的选项编号', 'scapy 解码出的选项名'), done=lidx(S(3), '选项个数', 'DHCP 包总长'), kv=KV([['固定头', '236 字节(op … file)'], ['magic cookie', '63 82 53 63'], ['选项', 'TLV:类型 1 字节 + 长度 1 字节 + 值'], ['sname / file', '192 字节,基本不用']], ['选项'])),
    step("租约时间线与本机真实续租:ipconfig 给出的是租约 1800 秒、T1 = 817 秒(约 13.6 分钟)、T2 = 1492 秒(24.9 分钟)。被动抓包 en0 从 09:55:46 起约 30 分钟,抓到本机 MAC 的 DHCP 报文 4 个(别的设备的另有 157 个,只统计个数):起点后 309.5 s 一对 REQUEST / ACK,1110.5 s 又一对;REQUEST 都是 IP 本机地址 → 默认网关的单播(以太网单播),ciaddr 是本机地址。两次 REQUEST 之间隔 801.0 秒,接近 ACK 里给的 T1 = 817 秒而不是规范默认的 900 秒。续租时每个 ACK 把租约重置到 1800 秒,所以本机一直不会过期。如果 T1 时没得到应答,到 T2 改成广播 REQUEST;1800 秒到期还没有回应就要放弃这个地址、重新从 DISCOVER 开始。", t=tl(S(4)), mark=lidx(S(4), '起点后   309.5 s  REQUEST', '起点后  1110.5 s  REQUEST', '两次 REQUEST'), done=lidx(S(4), '按 ipconfig 给出的值', '被动抓包', '起点后   309.5 s  ACK', '起点后  1110.5 s  ACK'), b=bars([['T1(ipconfig 给出)', 817, '817 s'], ['两次续租的间隔(实测)', 801, '801.0 s'], ['T2', 1492, '1492 s'], ['租约', 1800, '1800 s']], 1800, mark=[1], done=[0, 2, 3]), kv=KV([['续租(T1)', '单播 REQUEST → 服务器,ACK 回来'], ['实测间隔', '801.0 s(T1 = 817 s)'], ['T2', '没有应答则广播 REQUEST'], ['别的设备', '30 分钟里 157 个 DHCP 报文']], ['实测间隔'])),
    step("DHCP 给的配置和系统实际生效的是否一致:子网掩码 DHCP 给 255.255.252.0,ifconfig 里也是,前缀长度 /22,一致;广播地址一致;路由器 DHCP 给了 1 个,默认路由的网关就是它;DNS DHCP 给了 2 个(公共 DNS),scutil --dns 里出现的 nameserver 共 2 个,DHCP 给的 2 个都在里面。地址、掩码、网关、DNS、域名这些都不用手配,是 DHCP 一次交给客户端的。", t=tl(S(5)), mark=lidx(S(5), '子网掩码', '路由器', 'DNS'), done=lidx(S(5), '广播地址', '地址、掩码、网关'), kv=KV([['子网掩码', 'DHCP = ifconfig = /22'], ['路由器', '= 默认路由的网关'], ['DNS', '2 个,都出现在 scutil --dns']], ['路由器'])),
]
A = mkartw('w21', 21, '网络协议,DHCP,DORA,租约,T1,T2,BOOTP,真实验证,动画演示',
    '解码本机当前的 DHCP 租约(租约 1800 秒,T1 = 817 秒);实发一次 DHCPDISCOVER(伪造 MAC,不发 REQUEST)收到 114.2 ms 后的 OFFER;自己解码与 scapy 一致;30 分钟被动抓包抓到本机两次续租 REQUEST / ACK,间隔 801.0 秒;DHCP 配置与系统实际一致。',
    '你的设备一连上 Wi-Fi 就有了地址、网关和 DNS——是谁给的、怎么给的?租约到期之前设备做了什么?这篇解码本机的真实租约,向网关的 DHCP 服务器发一次真实的 DISCOVER 收下 OFFER,并用 30 分钟的被动抓包抓下本机自己的续租。',
    [('114.2 ms', '广播 DHCPDISCOVER 到收到网关的 OFFER 之间的时间'), ('801.0 秒', '被动抓包里本机两次续租 REQUEST 的间隔(ACK 里给的 T1 是 817 秒)'), ('279 字节', 'DHCPDISCOVER 的大小:236 字节固定头 + 4 字节 magic cookie + 39 字节选项')],
    [('DHCP 报文', '<p>DHCP 沿用了 BOOTP 的 236 字节固定头(op、xid、ciaddr、yiaddr、siaddr、giaddr、chaddr、sname、file),后面是 4 字节 magic cookie 和 TLV 格式的选项。租约、掩码、网关、DNS 等都是选项。</p>'),
     ('报文格式', '<p>固定头加选项:选项是类型、长度、值的重复。自己的解码器与 scapy 对同一个 OFFER 解出同样的 10 个选项。</p>'),
     ('DORA', '<p>客户端广播 DISCOVER,服务器回 OFFER(这里是 114.2 ms),客户端再发 REQUEST,服务器回 ACK。实验只做了前两步,没有发 REQUEST,所以没有占用地址。</p>'),
     ('租约与续租', '<p>本机租约 1800 秒。到 T1(ACK 里给 817 秒,实测续租间隔 801 秒)时单播 REQUEST 给原服务器,ACK 回来租约重置;没回应就在 T2 广播,到期则重新 DISCOVER。</p>'),
     ('配置生效', '<p>掩码、网关、DNS 都和 ifconfig、route、scutil 里的一致,说明系统直接采用 DHCP 给的配置。</p>')],
    steps,
    [ENV_W + '。第二节向局域网广播了一次 DHCPDISCOVER(用伪造的本地管理 MAC,没有发 REQUEST,服务器可能短暂保留了一个 offered 地址);第四节来自 30 分钟的被动抓包,其中别的设备的 DHCP 报文只统计个数;默认网关、服务器和本机地址做了遮盖',
     '没有验证:REQUEST / ACK 的第一次获取(完整的 DORA);T2 广播和租约过期后的重新开始;DHCP 中继(giaddr);服务器是否限制客户端的 MAC;OFFER 里 T1 = 900 而续租 ACK 里 T1 = 817 的差异原因;DHCP 与 ARP 冲突检测的配合'],
    'DHCP 四步')
